@contextmanager
def start_splunk_ao_span(splunk_ao_span: SplunkAOSpan) -> Generator[trace.Span, Any, None]:
    tracer_provider = _TRACE_PROVIDER_CONTEXT_VAR.get()
    if tracer_provider is None:
        tracer_provider = trace.get_tracer_provider()
        _TRACE_PROVIDER_CONTEXT_VAR.set(cast(TracerProvider, tracer_provider))
    tracer = tracer_provider.get_tracer("splunk-ao-tracer")
    is_conversation_root = not trace.get_current_span().get_span_context().is_valid and isinstance(
        splunk_ao_span, WorkflowSpan | AgentSpan
    )
    session_id = get_effective_session_id()
    with tracer.start_as_current_span(splunk_ao_span.name) as span:
        try:
            yield span
        finally:
            try:
                attributes = build_span_attributes(splunk_ao_span, session_id)
                if is_conversation_root:
                    attributes[GEN_AI_CONVERSATION_ROOT] = True
                for key, value in attributes.items():
                    span.set_attribute(key, value)
            except Exception:
                logger.warning("Failed to finalize Splunk AO span attributes", exc_info=True)

def _sync_log(
    self,
    func: F,
    *,
    name: str | None,
    span_type: SPAN_TYPE | None,
    params: dict[str, str | Callable] | None = None,
    dataset_record: DatasetRecord | None = None,
) -> F:
    """
    Internal method to handle logging for synchronous functions.

    Parameters
    ----------
    func
        The function to decorate
    name
        Custom name for the span
    span_type
        Type of span to create
    params
        Parameter mapping for extracting specific values

    Returns
    -------
        Decorated function that logs its execution
    """

    @wraps(func)
    def sync_wrapper(*args: Any, **kwargs: Any) -> Any:
        span_params = self._prepare_input(
            func=func,
            name=name or func.__name__,
            span_type=span_type,
            params=params,
            is_method=self._is_method(func),
            func_args=args,
            func_kwargs=kwargs,
        )
        if span_params is None:
            return func(*args, **kwargs)

        call_state = self._safe_prepare_call(span_type, span_params, dataset_record)

        try:
            result = func(*args, **kwargs)
        except BaseException as exc:
            _logger.error("Error while executing function in sync_wrapper", exc_info=True)
            if call_state is not None:
                self._finalize_call(span_type, span_params, None, call_state, error=exc)
            raise

        if call_state is None:
            return result
        return self._finalize_call(span_type, span_params, result, call_state)

    return cast(F, sync_wrapper)
